// HasTask applies the HasEdge predicate on the "task" edge.
func HasTask() predicate.ProofOfDelivery {
	return predicate.ProofOfDelivery(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2O, true, TaskTable, TaskColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasTaskWith applies the HasEdge predicate on the "task" edge with a given conditions (other predicates).
func HasTaskWith(preds ...predicate.Task) predicate.ProofOfDelivery {
	return predicate.ProofOfDelivery(func(s *sql.Selector) {
		step := newTaskStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ProofOfDelivery) predicate.ProofOfDelivery {
	return predicate.ProofOfDelivery(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ProofOfDelivery) predicate.ProofOfDelivery {
	return predicate.ProofOfDelivery(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ProofOfDelivery) predicate.ProofOfDelivery {
	return predicate.ProofOfDelivery(sql.NotPredicates(p))
}
